const InterfaceMetadata *FindInterface(const char *iid)
{
    if (!iid) return nullptr;
    for (const auto &item : interfaces) if (std::strcmp(item.iid, iid) == 0) return &item;
    return nullptr;
}

const MethodMetadata *FindMethod(const InterfaceMetadata &metadata, std::uint32_t slot)
{
    for (std::uint32_t index = 0; index < metadata.method_count; ++index)
        if (metadata.methods[index].slot == slot) return &metadata.methods[index];
    return nullptr;
}

